package app.yoru.mobile;

import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.*;
import android.net.*;
import android.os.*;
import android.text.InputType;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import javax.net.ssl.*;
import java.security.SecureRandom;
import java.security.cert.X509Certificate;

final class YoruVpn {
    static final int REQ_VPN=5401;
    private static String pending;
    private YoruVpn(){}
    static void open(Activity a){ArrayList<String> items=new ArrayList<>();items.add("Вставить подписку и обновить локации");items.add("Выбрать локацию");items.add("Режим: "+modeLabel(YoruApp.app().store.vpnMode()));items.add("Приложения через VPN");items.add(YoruVpnService.active()?"Отключить":"Подключить");items.add("Статус VPN");new AlertDialog.Builder(a).setTitle("YORU · встроенный VPN").setItems(items.toArray(new String[0]),(d,i)->{String x=items.get(i);if(x.startsWith("Вставить"))subscription(a);else if(x.startsWith("Выбрать"))locations(a);else if(x.startsWith("Режим"))mode(a);else if(x.startsWith("Приложения"))apps(a);else if(x.equals("Подключить"))connect(a);else if(x.equals("Отключить"))disconnect(a);else status(a);}).setMessage("Подписка сначала распаковывается через обычную сеть телефона без системного VPN, затем запускается Xray.").setNegativeButton("Закрыть",null).show();}
    static void refreshInline(Activity a,String url,Runnable done){refreshWork(a,url,"Загружаем подписку через сеть телефона…",false,done);}
    static void afterPermission(Activity a,int code){if(code==Activity.RESULT_OK&&pending!=null)start(a,pending);else Ui.toast(a,"VPN-разрешение не выдано");pending=null;}
    private static void subscription(Activity a){EditText input=new EditText(a);input.setSingleLine(false);input.setMinLines(2);input.setTextColor(Ui.TEXT);input.setHintTextColor(Ui.MUTED);input.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_URI);input.setText(YoruApp.app().store.vpnSubscriptionUrl());input.setHint("https://...");input.setPadding(Ui.dp(a,16),Ui.dp(a,12),Ui.dp(a,16),Ui.dp(a,12));input.setBackground(Ui.stroke(Ui.CARD,12,a));new AlertDialog.Builder(a).setTitle("VPN подписка").setMessage("Ссылка хранится только на устройстве. Импорт идёт через обычную сеть телефона, даже если VPN уже включён.").setView(input).setPositiveButton("Обновить",(d,w)->refresh(a,input.getText().toString().trim())).setNegativeButton("Отмена",null).show();}
    static void refresh(Activity a,String url){refreshWork(a,url,"Загружаем подписку через сеть телефона…",true,null);}
    private static void refreshWork(Activity a,String url,String message,boolean showLocations,Runnable done){if(url.isEmpty()){Ui.toast(a,"Вставьте ссылку подписки");if(done!=null)done.run();return;}ProgressDialog wait=new ProgressDialog(a);wait.setMessage(message);wait.setCancelable(false);wait.show();YoruApp.app().io.execute(()->{try{JSONArray list=load(url);JSONObject selected=save(url,list);YoruApp.app().main.post(()->{if(dead(a))return;wait.dismiss();Ui.toast(a,"Локаций найдено: "+list.length());if(showLocations)locations(a);if(done!=null)done.run();});}catch(Exception e){YoruApp.app().main.post(()->{if(dead(a))return;wait.dismiss();Ui.toast(a,"Не удалось распаковать подписку через сеть телефона");if(done!=null)done.run();});}});}
    static void locations(Activity a){try{JSONArray list=YoruApp.app().store.vpnProfiles();if(list.length()==0){Ui.toast(a,"Сначала обновите подписку");return;}String[] names=new String[list.length()];int selected=0;String id=YoruApp.app().store.vpnSelected();for(int i=0;i<list.length();i++){JSONObject p=list.optJSONObject(i);names[i]=p==null?"VPN":YoruVpnProfile.label(p);if(p!=null&&p.optString("id").equals(id))selected=i;}new AlertDialog.Builder(a).setTitle("VPN локация").setSingleChoiceItems(names,selected,(d,which)->{JSONObject p=list.optJSONObject(which);if(p!=null){YoruApp.app().store.vpnSelected(p.optString("id"));Ui.toast(a,"Выбрано: "+YoruVpnProfile.label(p).replace('\n',' '));}d.dismiss();}).setNegativeButton("Закрыть",null).show();}catch(Throwable e){Ui.toast(a,"Не удалось открыть список локаций");}}
    static void mode(Activity a){String[] labels={"Только YORU","Выбранные приложения","Все приложения"};String[] values={"self","selected","all"};String cur=YoruApp.app().store.vpnMode();int checked=0;for(int i=0;i<values.length;i++)if(values[i].equals(cur))checked=i;new AlertDialog.Builder(a).setTitle("Режим VPN").setSingleChoiceItems(labels,checked,(d,which)->{YoruApp.app().store.vpnMode(values[which]);Ui.toast(a,"VPN: "+labels[which]);d.dismiss();}).setNegativeButton("Закрыть",null).show();}
    static void apps(Activity a){try{List<ApplicationInfo> all=a.getPackageManager().getInstalledApplications(0);ArrayList<ApplicationInfo> launch=new ArrayList<>();for(ApplicationInfo app:all)if(a.getPackageManager().getLaunchIntentForPackage(app.packageName)!=null)launch.add(app);launch.sort((x,y)->label(a,x).compareToIgnoreCase(label(a,y)));String[] names=new String[launch.size()];boolean[] checked=new boolean[launch.size()];HashSet<String> saved=new HashSet<>();JSONArray arr=YoruApp.app().store.vpnApps();for(int i=0;i<arr.length();i++)saved.add(arr.optString(i));for(int i=0;i<launch.size();i++){ApplicationInfo info=launch.get(i);names[i]=label(a,info);checked[i]=saved.contains(info.packageName);}new AlertDialog.Builder(a).setTitle("Приложения через VPN").setMultiChoiceItems(names,checked,(d,which,on)->checked[which]=on).setPositiveButton("Сохранить",(d,w)->{JSONArray out=new JSONArray();for(int i=0;i<checked.length;i++)if(checked[i])out.put(launch.get(i).packageName);YoruApp.app().store.vpnApps(out);Ui.toast(a,"Список VPN-приложений сохранён");}).setNegativeButton("Отмена",null).show();}catch(Throwable e){Ui.toast(a,"Не удалось открыть список приложений");}}
    static void connect(Activity a){String url=YoruApp.app().store.vpnSubscriptionUrl().trim();if(!url.isEmpty()){connectAfterRefresh(a,url);return;}beginStored(a);}
    private static void connectAfterRefresh(Activity a,String url){ProgressDialog wait=new ProgressDialog(a);wait.setMessage("Сначала распаковываем подписку через сеть телефона…");wait.setCancelable(false);wait.show();YoruApp.app().io.execute(()->{try{JSONArray list=load(url);JSONObject p=save(url,list);if(p==null)throw new IOException("empty");YoruVpnConfig.build(p);YoruApp.app().main.post(()->{if(dead(a))return;wait.dismiss();begin(a,p);});}catch(Exception e){YoruApp.app().main.post(()->{if(dead(a))return;wait.dismiss();Ui.toast(a,"VPN не включён: сначала нужно распаковать рабочую подписку");});}});}
    private static void beginStored(Activity a){JSONObject p=YoruVpnProfile.selected(YoruApp.app().store.vpnProfiles(),YoruApp.app().store.vpnSelected());if(p==null){Ui.toast(a,"Сначала добавьте VPN подписку");return;}try{YoruVpnConfig.build(p);begin(a,p);}catch(Exception e){Ui.toast(a,"Этот VPN-профиль не удалось подготовить для Xray");}}
    private static void begin(Activity a,JSONObject p){if(!YoruVpnCore.available()){Ui.toast(a,"Xray core недоступен в этой сборке");return;}try{pending=p.toString();if(Build.VERSION.SDK_INT>=33&&a.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)a.requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},5402);Intent prepare=VpnService.prepare(a);if(prepare!=null)a.startActivityForResult(prepare,REQ_VPN);else afterPermission(a,Activity.RESULT_OK);}catch(Exception e){Ui.toast(a,"Не удалось запросить VPN-разрешение");}}
    private static void start(Activity a,String profile){Intent i=new Intent(a,YoruVpnService.class).setAction(YoruVpnService.ACTION_CONNECT).putExtra(YoruVpnService.EXTRA_PROFILE,profile).putExtra(YoruVpnService.EXTRA_MODE,YoruApp.app().store.vpnMode());ArrayList<String> apps=new ArrayList<>();JSONArray arr=YoruApp.app().store.vpnApps();for(int n=0;n<arr.length();n++){String p=arr.optString(n);if(!p.isEmpty())apps.add(p);}i.putStringArrayListExtra(YoruVpnService.EXTRA_APPS,apps);if(Build.VERSION.SDK_INT>=26)a.startForegroundService(i);else a.startService(i);Ui.toast(a,"VPN подключается через Xray…");}
    static void disconnect(Activity a){a.startService(new Intent(a,YoruVpnService.class).setAction(YoruVpnService.ACTION_DISCONNECT));Ui.toast(a,"VPN отключается");}
    static void status(Activity a){new AlertDialog.Builder(a).setTitle("VPN статус").setMessage(YoruVpnService.text()+"\n\nЛокаций: "+YoruApp.app().store.vpnProfiles().length()+"\nРежим: "+modeLabel(YoruApp.app().store.vpnMode())+"\nИмпорт подписки: через сеть телефона без активного VPN").setPositiveButton("Понятно",null).show();}
    private static JSONObject save(String url,JSONArray list){YoruApp.app().store.vpnSubscriptionUrl(url);YoruApp.app().store.vpnProfiles(list);String old=YoruApp.app().store.vpnSelected();JSONObject chosen=YoruVpnProfile.selected(list,old);if(chosen!=null)YoruApp.app().store.vpnSelected(chosen.optString("id"));return chosen;}
    private static JSONArray load(String input)throws Exception{JSONArray direct=YoruVpnProfile.parseSubscription(input);if(direct.length()>0)return direct;Exception last=null;for(String url:variants(input)){for(String ua:agents()){for(boolean loose:new boolean[]{false,true})try{String body=download(url,ua,loose);JSONArray parsed=YoruVpnProfile.parseSubscription(body);if(parsed.length()>0)return parsed;}catch(Exception e){last=e;}}}throw last==null?new IOException("empty"):last;}
    private static String[] agents(){return new String[]{"v2rayNG/2.3.7","v2RayTun/5.25.82","NekoBox/1.3.8","HiddifyNext/2.5.7","ClashMetaForAndroid/2.11","sing-box/1.11","YORU Android"};}
    private static ArrayList<String> variants(String input){ArrayList<String> out=new ArrayList<>();String u=input.trim();if(!(u.startsWith("http://")||u.startsWith("https://")))return out;out.add(u);if(u.startsWith("https://"))out.add("http://"+u.substring(8));String sep=u.contains("?")?"&":"?";out.add(u+sep+"format=v2ray");out.add(u+sep+"type=v2ray");out.add(u+sep+"format=base64");out.add(u+sep+"format=clash");out.add(u+sep+"format=sing-box");return out;}
    private static String download(String url,String ua,boolean loose)throws Exception{HttpURLConnection c=open(new URL(url));c.setInstanceFollowRedirects(true);c.setConnectTimeout(15000);c.setReadTimeout(25000);c.setRequestProperty("User-Agent",ua);c.setRequestProperty("Accept","text/plain, application/json, application/yaml, */*");if(loose&&c instanceof HttpsURLConnection)loose((HttpsURLConnection)c);int code=c.getResponseCode();if(code<200||code>=300)throw new IOException(String.valueOf(code));try(InputStream in=c.getInputStream()){return ApiRepository.readStream(in,12*1024*1024);}}
    private static HttpURLConnection open(URL url)throws IOException{Network n=plainNetwork();URLConnection c=n==null?url.openConnection():n.openConnection(url);return (HttpURLConnection)c;}
    private static Network plainNetwork(){try{ConnectivityManager cm=(ConnectivityManager)YoruApp.app().getSystemService(Context.CONNECTIVITY_SERVICE);if(cm==null)return null;for(Network n:cm.getAllNetworks()){NetworkCapabilities cap=cm.getNetworkCapabilities(n);if(cap!=null&&cap.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)&&!cap.hasTransport(NetworkCapabilities.TRANSPORT_VPN))return n;}}catch(Throwable ignored){}return null;}
    private static void loose(HttpsURLConnection c)throws Exception{TrustManager[] trust=new TrustManager[]{new X509TrustManager(){public void checkClientTrusted(X509Certificate[] x,String a){}public void checkServerTrusted(X509Certificate[] x,String a){}public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}}};SSLContext ctx=SSLContext.getInstance("TLS");ctx.init(null,trust,new SecureRandom());c.setSSLSocketFactory(ctx.getSocketFactory());c.setHostnameVerifier((h,s)->true);}
    static String modeLabel(String m){if("all".equals(m))return "все приложения";if("selected".equals(m))return "выбранные приложения";return "только YORU";}
    private static String label(Context c,ApplicationInfo i){try{return String.valueOf(c.getPackageManager().getApplicationLabel(i));}catch(Exception e){return i.packageName;}}
    private static boolean dead(Activity a){return a.isFinishing()||a.isDestroyed();}
}
